// Rules the brief requires, as polygraph invariants.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const same = (a, b) => a.role === b.role && a.term === b.term;

export const stateInvariants = [
  { name: 'role-is-known', pred: (s) => ROLES.includes(s.role) },
  { name: 'term-in-0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // A leader was a candidate first in its own term, so term 0 has no leader.
  { name: 'no-leader-in-term-0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
];

export const transitionInvariants = [
  { name: 'term-never-goes-down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only-election-or-newer-term-changes-term',
    pred: (pre, a, d, post) => post.term === pre.term || a === 'electionTimeout' || a === 'newerTermSeen',
  },
  {
    name: 'election-raises-term-by-1',
    pred: (pre, a, d, post) => a !== 'electionTimeout' || same(pre, post) || (post.term === pre.term + 1 && post.role === 'candidate'),
  },
  {
    name: 'leader-was-candidate-in-same-term',
    pred: (pre, a, d, post) =>
      post.role !== 'leader' || pre.role === 'leader' || (pre.role === 'candidate' && pre.term === post.term && a === 'electionWon'),
  },
  {
    name: 'leader-only-stays-leader-in-same-term',
    pred: (pre, a, d, post) => !(pre.role === 'leader' && post.role === 'leader') || pre.term === post.term,
  },
  { name: 'shutdown-stays-shutdown', pred: (pre, a, d, post) => pre.role !== 'shutdown' || same(pre, post) },
  {
    name: 'newer-term-is-strictly-newer-and-in-range',
    pred: (pre, a, d, post) =>
      a !== 'newerTermSeen' || same(pre, post) ||
      (post.role === 'follower' && post.term === d.term && d.term > pre.term && d.term >= 1 && d.term <= 3),
  },
  { name: 'shutdown-keeps-term', pred: (pre, a, d, post) => a !== 'shutdown' || post.term === pre.term },
  { name: 'leader-never-times-out', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.role === 'leader') || same(pre, post) },
];

