// Captures NDJSON traces from the real implementation: a BFS over every
// reachable state, firing every (command, payload) of the contract's domain,
// one trace file per path (each path replayed from a fresh host).
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];
const STEPS: { action: string; data: Record<string, number> }[] = [
  { action: 'electionTimeout', data: {} },
  { action: 'electionWon', data: {} },
  ...TERMS.map((term) => ({ action: 'newerTermSeen', data: { term } })),
  { action: 'quorumLost', data: {} },
  { action: 'shutdown', data: {} },
];

const fire = (h: Host, s: (typeof STEPS)[number]) =>
  s.action === 'newerTermSeen' ? h.newerTermSeen(s.data.term) : (h as any)[s.action]();

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

const seen = new Map<string, number[]>([[JSON.stringify({ role: 'follower', term: 0 }), []]]);
const queue: number[][] = [[]];
let n = 0;
while (queue.length) {
  const path = queue.shift()!;
  for (let i = 0; i < STEPS.length; i++) {
    const h = await createHost();
    const lines: string[] = [];
    for (const j of [...path, i]) {
      const pre = await h.node();
      await fire(h, STEPS[j]);
      const post = await h.node();
      lines.push(JSON.stringify({ pre, action: STEPS[j].action, data: STEPS[j].data, post }));
    }
    writeFileSync(new URL(`t${String(n++).padStart(4, '0')}.ndjson`, dir), lines.join('\n') + '\n');
    const key = JSON.stringify(await h.node());
    if (!seen.has(key)) { seen.set(key, [...path, i]); queue.push([...path, i]); }
  }
}
console.log(`${n} traces, ${seen.size} states`);

