'use strict';
// SAM v2 strict-profile specification of src/node.ts (the stateful core).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_TERM = 3;
// role: 'follower' | 'candidate' | 'leader' | 'shutdown'
const INITIAL_STATE = { role: 'follower', term: 0 };

const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
    },
    actions: {
      electionTimeout: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      electionWon: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      newerTermSeen: {
        action: (data = {}) => ({ ...data }),
        schema: { term: { type: 'number', required: true } },
        domain: TERMS.map((term) => ({ term })),
      },
      quorumLost: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      shutdown: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
    },
    acceptors: {
      electionTimeout: (model) => (proposal, { reject, next }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role === 'leader') return reject('leader-does-not-time-out');
        if (model.term >= MAX_TERM) return reject('no-term-after-3');
        next.role = 'candidate';
        next.term = model.term + 1;
      },
      electionWon: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role !== 'candidate') return reject('not-a-candidate');
        next.role = 'leader';
        unchanged('term');
      },
      newerTermSeen: (model) => (proposal, { reject, next }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        const t = proposal.term;
        if (typeof t !== 'number' || !Number.isInteger(t) || t < 1 || t > MAX_TERM) return reject('term-out-of-range');
        if (t <= model.term) return reject('term-not-newer');
        next.role = 'follower';
        next.term = t;
      },
      quorumLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role !== 'leader') return reject('not-the-leader');
        next.role = 'follower';
        unchanged('term');
      },
      shutdown: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        next.role = 'shutdown';
        unchanged('term');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  electionTimeout: (data = {}) => intents.electionTimeout(data),
  electionWon: (data = {}) => intents.electionWon(data),
  newerTermSeen: (data = {}) => intents.newerTermSeen(data),
  quorumLost: (data = {}) => intents.quorumLost(data),
  shutdown: (data = {}) => intents.shutdown(data),
};

module.exports = { instance, init, actions, getState, setState };

