const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const VOTES = ['nobody', 'itself', 'n1', 'n2'];
const same = (a, b) => a.role === b.role && a.term === b.term && a.votedFor === b.votedFor;

export const stateInvariants = [
  { name: 'role-is-known', pred: (s) => ROLES.includes(s.role) },
  { name: 'vote-is-known', pred: (s) => VOTES.includes(s.votedFor) },
  { name: 'term-in-0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // A leader was a candidate first in its own term, so term 0 has no leader.
  { name: 'no-leader-in-term-0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
  // A candidate or leader started its own election in this term and voted for itself.
  { name: 'candidate-and-leader-voted-for-itself', pred: (s) => !(s.role === 'candidate' || s.role === 'leader') || s.votedFor === 'itself' },
  { name: 'no-vote-in-term-0', pred: (s) => s.term !== 0 || s.votedFor === 'nobody' },
];

export const transitionInvariants = [
  { name: 'term-never-goes-down', pred: (pre, a, d, post) => post.term >= pre.term },
