      (post.role === 'follower' && post.term === d.term && post.votedFor === 'nobody' && d.term > pre.term && d.term >= 1 && d.term <= 3),
  },
  { name: 'shutdown-keeps-term-and-vote', pred: (pre, a, d, post) => a !== 'shutdown' || (post.term === pre.term && post.votedFor === pre.votedFor) },
