{
  "name": "consensus-node-role-term-and-vote",
  "stateKeys": ["role", "term", "votedFor"],
  "initState": { "role": "follower", "term": 0, "votedFor": "nobody" },
  "terminalStates": ["shutdown"],
  "actions": {
    "electionTimeout": { "dataFields": {} },
    "electionWon": { "dataFields": {} },
    "newerTermSeen": { "dataFields": { "term": "number" } },
    "quorumLost": { "dataFields": {} },
    "shutdown": { "dataFields": {} },
    "voteRequested": { "dataFields": { "candidate": "string", "term": "number" } }
  },
  "dataDomain": {
    "newerTermSeen": { "term": [-1, 0, 1, 2, 3, 4, 1.5] },
    "voteRequested": { "candidate": ["n1", "n2", "n3", "itself", "nobody"], "term": [0, 1, 2, 3, 4, 1.5] }
  },
  "specialRules": [
    { "name": "shut-down-refuses-all", "note": "once shut down, every command is refused" },
    { "name": "no-term-after-3", "note": "electionTimeout refused in term 3" },
    { "name": "term-out-of-range", "note": "newerTermSeen / voteRequested refused unless term is an integer in 1..3" },
    { "name": "term-not-newer", "note": "newerTermSeen refused unless strictly newer than current term" },
    { "name": "unknown-candidate", "note": "voteRequested refused unless candidate is n1 or n2" },
    { "name": "vote-older-term", "note": "voteRequested for an older term is not granted" },
    { "name": "already-voted", "note": "same-term vote granted only to a follower that has not voted, or to the candidate already voted for" }
  ],
  "noOpRule": "a refused command leaves post == pre"
}

// Captures NDJSON traces from the real implementation: a BFS over every
// reachable state, firing every (command, payload) of the contract's domain,
// one trace file per path (each path replayed from a fresh host).
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];
const VOTE_TERMS = [0, 1, 2, 3, 4, 1.5];
const CANDIDATES = ['n1', 'n2', 'n3', 'itself', 'nobody'];
const STEPS: { action: string; data: Record<string, any> }[] = [
  { action: 'electionTimeout', data: {} },
  { action: 'electionWon', data: {} },
  ...TERMS.map((term) => ({ action: 'newerTermSeen', data: { term } })),
  { action: 'quorumLost', data: {} },
  { action: 'shutdown', data: {} },
  ...CANDIDATES.flatMap((candidate) => VOTE_TERMS.map((term) => ({ action: 'voteRequested', data: { candidate, term } }))),
];

const fire = (h: Host, s: (typeof STEPS)[number]) =>
  s.action === 'newerTermSeen' ? h.newerTermSeen(s.data.term)
  : s.action === 'voteRequested' ? h.voteRequested(s.data.candidate, s.data.term)
  : (h as any)[s.action]();

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

const seen = new Map<string, number[]>([[JSON.stringify(await (await createHost()).node()), []]]);
const queue: number[][] = [[]];
let n = 0;
while (queue.length) {
  const path = queue.shift()!;
  for (let i = 0; i < STEPS.length; i++) {
    const h = await createHost();
    const lines: string[] = [];
    for (const j of [...path, i]) {
      const pre = await h.node();
      await fire(h, STEPS[j]);
      const post = await h.node();
      lines.push(JSON.stringify({ pre, action: STEPS[j].action, data: STEPS[j].data, post }));
    }
    writeFileSync(new URL(`t${String(n++).padStart(4, '0')}.ndjson`, dir), lines.join('\n') + '\n');
    const key = JSON.stringify(await h.node());
    if (!seen.has(key)) { seen.set(key, [...path, i]); queue.push([...path, i]); }
  }
}
console.log(`${n} traces, ${seen.size} states`);

// Rules the brief requires, as polygraph invariants.
const ROLES = ['follower', 'candidate', 'leader', 'shutdown'];
const VOTES = ['nobody', 'itself', 'n1', 'n2'];
const same = (a, b) => a.role === b.role && a.term === b.term && a.votedFor === b.votedFor;

export const stateInvariants = [
  { name: 'role-is-known', pred: (s) => ROLES.includes(s.role) },
  { name: 'vote-is-known', pred: (s) => VOTES.includes(s.votedFor) },
  { name: 'term-in-0..3', pred: (s) => Number.isInteger(s.term) && s.term >= 0 && s.term <= 3 },
  // A leader was a candidate first in its own term, so term 0 has no leader.
  { name: 'no-leader-in-term-0', pred: (s) => !(s.role === 'leader' && s.term === 0) },
  // A candidate or leader started its own election in this term and voted for itself.
  { name: 'candidate-and-leader-voted-for-itself', pred: (s) => !(s.role === 'candidate' || s.role === 'leader') || s.votedFor === 'itself' },
  { name: 'no-vote-in-term-0', pred: (s) => s.term !== 0 || s.votedFor === 'nobody' },
];

export const transitionInvariants = [
  { name: 'term-never-goes-down', pred: (pre, a, d, post) => post.term >= pre.term },
  {
    name: 'only-election-newer-term-or-vote-changes-term',
    pred: (pre, a, d, post) => post.term === pre.term || ['electionTimeout', 'newerTermSeen', 'voteRequested'].includes(a),
  },
  {
    name: 'election-raises-term-by-1-and-votes-itself',
    pred: (pre, a, d, post) =>
      a !== 'electionTimeout' || same(pre, post) ||
      (post.term === pre.term + 1 && post.role === 'candidate' && post.votedFor === 'itself'),
  },
  {
    name: 'leader-was-candidate-in-same-term',
    pred: (pre, a, d, post) =>
      post.role !== 'leader' || pre.role === 'leader' || (pre.role === 'candidate' && pre.term === post.term && a === 'electionWon'),
  },
  {
    name: 'leader-only-stays-leader-in-same-term',
    pred: (pre, a, d, post) => !(pre.role === 'leader' && post.role === 'leader') || pre.term === post.term,
  },
  { name: 'shutdown-stays-shutdown', pred: (pre, a, d, post) => pre.role !== 'shutdown' || same(pre, post) },
  {
    name: 'newer-term-is-strictly-newer-in-range-and-unvoted',
    pred: (pre, a, d, post) =>
      a !== 'newerTermSeen' || same(pre, post) ||
      (post.role === 'follower' && post.term === d.term && post.votedFor === 'nobody' && d.term > pre.term && d.term >= 1 && d.term <= 3),
  },
  { name: 'shutdown-keeps-term-and-vote', pred: (pre, a, d, post) => a !== 'shutdown' || (post.term === pre.term && post.votedFor === pre.votedFor) },
  { name: 'leader-never-times-out', pred: (pre, a, d, post) => !(a === 'electionTimeout' && pre.role === 'leader') || same(pre, post) },
  // Votes at most once in a term: within a term, the vote only moves from nobody.
  {
    name: 'vote-at-most-once-per-term',
    pred: (pre, a, d, post) => post.term !== pre.term || post.votedFor === pre.votedFor || pre.votedFor === 'nobody',
  },
  {
    name: 'vote-only-to-valid-request',
    pred: (pre, a, d, post) =>
      a !== 'voteRequested' || same(pre, post) ||
      ((d.candidate === 'n1' || d.candidate === 'n2') && Number.isInteger(d.term) && d.term >= 1 && d.term <= 3 &&
        d.term >= pre.term && post.term === d.term && post.votedFor === d.candidate && post.role === 'follower'),
  },
  {
    name: 'newer-term-vote-is-granted',
    pred: (pre, a, d, post) =>
      a !== 'voteRequested' || pre.role === 'shutdown' || !(d.candidate === 'n1' || d.candidate === 'n2') ||
      !(Number.isInteger(d.term) && d.term >= 1 && d.term <= 3) || d.term <= pre.term ||
      (post.role === 'follower' && post.term === d.term && post.votedFor === d.candidate),
  },
  {
    name: 'same-term-vote-only-from-unvoted-follower',
    pred: (pre, a, d, post) =>
      a !== 'voteRequested' || post.term !== pre.term || post.votedFor === pre.votedFor ||
      (pre.role === 'follower' && pre.votedFor === 'nobody'),
  },
];

