4	const { createInstance } = require('@cognitive-fab/sam-pattern');
5	
6	const instance = createInstance({ strict: true, hasAsyncActions: false });
7	
8	const MAX_TERM = 3;
9	// role: 'follower' | 'candidate' | 'leader' | 'shutdown'
10	// votedFor: 'nobody' | 'itself' | 'n1' | 'n2' (the vote in the current term)
11	const INITIAL_STATE = { role: 'follower', term: 0, votedFor: 'nobody' };
12	
13	const TERMS = [-1, 0, 1, 2, 3, 4, 1.5];
14	const VOTE_TERMS = [0, 1, 2, 3, 4, 1.5];
15	const CANDIDATES = ['n1', 'n2', 'n3', 'itself', 'nobody'];
16	
17	const validTerm = (t) => typeof t === 'number' && Number.isInteger(t) && t >= 1 && t <= MAX_TERM;
18	
19	const control = instance({
20	  initialState: { ...INITIAL_STATE },
21	  component: {
22	    modelShape: {
23	      role: { type: 'string' },
24	      term: { type: 'number' },
25	      votedFor: { type: 'string' },
26	    },
27	    actions: {
28	      electionTimeout: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
29	      electionWon: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
30	      electionLost: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
31	      newerTermSeen: {
32	        action: (data = {}) => ({ ...data }),
33	        schema: { term: { type: 'number', required: true } },
34	        domain: TERMS.map((term) => ({ term })),
35	      },
36	      quorumLost: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
37	      shutdown: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
38	      voteRequested: {
39	        action: (data = {}) => ({ ...data }),
40	        schema: { candidate: { type: 'string', required: true }, term: { type: 'number', required: true } },
41	        domain: CANDIDATES.flatMap((candidate) => VOTE_TERMS.map((term) => ({ candidate, term }))),
42	      },
43	    },
