const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      role: { type: 'string' },
      term: { type: 'number' },
      votedFor: { type: 'string' },
      paused: { type: 'boolean' },
    },
    actions: {
      electionTimeout: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      electionWon: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      electionLost: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      newerTermSeen: {
        action: (data = {}) => ({ ...data }),
        schema: { term: { type: 'number', required: true } },
        domain: TERMS.map((term) => ({ term })),
      },
      quorumLost: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      shutdown: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      pause: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      resume: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      voteRequested: {
        action: (data = {}) => ({ ...data }),
        schema: { candidate: { type: 'string', required: true }, term: { type: 'number', required: true } },
        domain: CANDIDATES.flatMap((candidate) => VOTE_TERMS.map((term) => ({ candidate, term }))),
      },
    },
    acceptors: {
      electionTimeout: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role === 'leader') return reject('leader-does-not-time-out');
        if (model.paused) return reject('paused-starts-no-election');
        if (model.term >= MAX_TERM) return reject('no-term-after-3');
        next.role = 'candidate';
        next.term = model.term + 1;
        next.votedFor = 'itself';
        unchanged('paused');
      },
      electionWon: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role !== 'candidate') return reject('not-a-candidate');
        next.role = 'leader';
        unchanged('term', 'votedFor', 'paused');
      },
      electionLost: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role !== 'candidate') return reject('not-a-candidate');
        next.role = 'follower';
        unchanged('term', 'votedFor', 'paused');
