        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        next.role = 'shutdown';
        unchanged('term', 'votedFor', 'paused');
      },
      pause: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (model.role !== 'follower') return reject('only-follower-pauses');
        if (model.paused) return reject('already-paused');
        next.paused = true;
        unchanged('role', 'term', 'votedFor');
      },
      resume: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.role === 'shutdown') return reject('shut-down-refuses-all');
        if (!model.paused) return reject('not-paused');
        next.paused = false;
        unchanged('role', 'term', 'votedFor');
      },
      voteRequested: (model) => (proposal, { reject, next, unchanged }) => {
