{
  "name": "consensus-node-role-term-and-vote",
  "stateKeys": ["role", "term", "votedFor"],
  "initState": { "role": "follower", "term": 0, "votedFor": "nobody" },
  "terminalStates": ["shutdown"],
  "actions": {
    "electionTimeout": { "dataFields": {} },
    "electionWon": { "dataFields": {} },
    "electionLost": { "dataFields": {} },
    "newerTermSeen": { "dataFields": { "term": "number" } },
    "quorumLost": { "dataFields": {} },
    "shutdown": { "dataFields": {} },
    "voteRequested": { "dataFields": { "candidate": "string", "term": "number" } }
  },
  "dataDomain": {
    "newerTermSeen": { "term": [-1, 0, 1, 2, 3, 4, 1.5] },
    "voteRequested": { "candidate": ["n1", "n2", "n3", "itself", "nobody"], "term": [0, 1, 2, 3, 4, 1.5] }
  },
  "specialRules": [
    { "name": "shut-down-refuses-all", "note": "once shut down, every command is refused" },
    { "name": "no-term-after-3", "note": "electionTimeout refused in term 3" },
