    pred: (pre, a, d, post) =>
      !(a === 'newerTermSeen' && pre.paused && pre.role === 'follower' && Number.isInteger(d.term) && d.term > pre.term && d.term <= 3) ||
      (post.term === d.term && post.paused),
  },
];

